; stale.asm -- chapter 9: WHERE IT BREAKS: SBC HL,DE and a carry left over
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "stale.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
        ld a, 2
        cp 3                    ; 2 < 3: the carry is set
        ld hl, $1000
        ld de, $0001
        sbc hl, de              ; $1000 - $0001 - carry
p1:     or a                    ; the carry cleared first
        ld hl, $1000
        sbc hl, de              ; $1000 - $0001
p2:
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
